import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <nav style={{ background: '#111', color: '#fff', padding: '0 24px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: 56 }}>
      <Link to="/" style={{ color: '#fff', fontWeight: 700, fontSize: 20, textDecoration: 'none' }}>
        RecipeHub
      </Link>
      <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
        <span style={{ fontSize: 14, color: '#aaa' }}>{user?.username}</span>
        <Link to="/groups" style={linkStyle}>그룹</Link>
        <Link to="/my-recipes" style={linkStyle}>마이페이지</Link>
        {user?.role === 'ADMIN' && (
          <Link to="/admin" style={{ ...linkStyle, color: '#fbbf24' }}>관리자</Link>
        )}
        <Link to="/recipes/new" style={{ ...linkStyle, background: '#fff', color: '#111', padding: '6px 14px', borderRadius: 6, fontWeight: 600 }}>
          + 레시피 등록
        </Link>
        <button onClick={handleLogout} style={btnStyle}>로그아웃</button>
      </div>
    </nav>
  );
}

const linkStyle = { color: '#fff', textDecoration: 'none', fontSize: 14 };
const btnStyle = { background: 'transparent', border: '1px solid #555', color: '#aaa', cursor: 'pointer', fontSize: 13, padding: '5px 12px', borderRadius: 5 };
